#include "../src/hpack.hpp"
#include "../src/blake3.hpp"
#include <iostream>
vpn::Bytes unhex(const std::string& s){vpn::Bytes out;if(s=="-")return out;if(s.size()%2)throw std::runtime_error("hex");for(size_t i=0;i<s.size();i+=2){int a=vpn::hex_digit(s[i]),b=vpn::hex_digit(s[i+1]);if(a<0||b<0)throw std::runtime_error("hex");out.push_back(uint8_t(a*16+b));}return out;}
int main(){std::string line;while(std::getline(std::cin,line)){try{std::istringstream in(line);std::string op,key,nonce,data,aad;in>>op>>key>>nonce>>data>>aad;vpn::Bytes result;if(op=="blake3"){std::cout<<vpn::hex_bytes(vpn::blake3_short_hash(unhex(key)));}else if(op=="blake3-derive"){std::cout<<vpn::hex_bytes(vpn::blake3_derive(vpn::from_bytes(unhex(key)),unhex(nonce)));}else if(op=="huffman")std::cout<<vpn::huffman_decode(unhex(key));else if(op=="hpack"){vpn::Hpack h;auto fields=h.decode(unhex(key));vpn::Json j=vpn::Json::obj();for(const auto& p:fields)j[p.first]=vpn::Json(p.second);std::cout<<vpn::json_dump(j);}else {result=vpn::aead(op,unhex(key),unhex(nonce),unhex(data),unhex(aad));std::cout<<vpn::hex_bytes(result);}std::cout<<'\n';}catch(const std::exception& e){std::cout<<"ERROR: "<<e.what()<<'\n';}}}
